// Slack slash commands arrive as form-encoded fields under .body
const raw = $input.first().json;
const b = raw.body || raw;

let command = String(b.text || raw.text || '').trim();

// A bare `/nexus` used to throw. The user had already been acknowledged by then,
// so they simply never heard back. Answer with usage instead.
if (!command) {
  command = 'The user sent no command text. Reply with a short usage hint: ' +
            '`/nexus find lead <name>` or `/nexus update lead <name> status <status>`.';
}

// ---- TENANT (2 Sep 2026) --------------------------------------------------
// The CRM agent reads and WRITES the leads table as service_role, which is
// BYPASSRLS. Unscoped, 'Search Leads' would return any dealership's customers
// to whoever typed the command, and 'Update Lead Status' -- which matches on
// email alone -- would update the same-email lead in EVERY dealership once
// leads.email is unique per tenant rather than globally.
//
// The signal is the authenticated caller: this webhook is JWT-guarded, and
// 'Tenant For JWT User' looks that Supabase user up in tenant_members. If that
// does not answer and exactly one dealership is configured, we name that one
// explicitly -- today's behaviour stated rather than defaulted. With two or
// more configured the tenant is null, both tools fall back to a sentinel uuid
// that matches zero rows (so a command reads and writes NOTHING rather than
// the wrong dealership's rows), and the audit row says TENANT UNRESOLVED.
const NEXUS_BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // Tenant A
const NEXUS_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let nexusMap = {};
try { nexusMap = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { nexusMap = {}; }
if (!nexusMap || typeof nexusMap !== 'object' || !Object.keys(nexusMap).length) nexusMap = NEXUS_BUILTIN;
const nexusKeys = Object.keys(nexusMap);

let tenant = '';
let tenantSource = '';
try {
  const row = $('Tenant For JWT User').all().map(i => i.json).find(x => x && x.tenant_id);
  if (row) { tenant = String(row.tenant_id); tenantSource = 'jwt_tenant_member'; }
} catch (e) { /* node did not run */ }
if (!NEXUS_UUID.test(tenant) && nexusKeys.length === 1) {
  tenant = String(nexusMap[nexusKeys[0]] || '');
  tenantSource = 'sole_configured_tenant';
}
if (!NEXUS_UUID.test(tenant)) { tenant = null; tenantSource = 'unresolved'; }

return [{ json: {
  command,
  user: b.user_name || b.user_id || 'unknown',
  channel: b.channel_name || b.channel_id || null,
  tenant_id: tenant,
  tenant_source: tenantSource,
  // Slack's 3-second slash-command deadline cannot be met by an AI agent with
  // tool calls, so the webhook acks immediately and the answer is delivered
  // here afterwards. Valid for 30 minutes / 5 posts.
  response_url: b.response_url || null
} }];

// Format Slack Response
// -----------------------------------------------------------------------------
// Added: a destination check on response_url.
//
// 'Post Answer to Slack' POSTs to whatever URL arrives in the request body
// (`b.response_url` in 'Extract Command'). On a webhook that any caller can
// reach, that turns this box into an exfiltration relay: send a command, point
// response_url at your own server, and the CRM agent's answer -- lead names,
// emails, statuses -- is delivered to you. Genuine Slack response_urls are
// always on https://hooks.slack.com/, so require that.
//
// Throwing here (rather than silently dropping) is deliberate: a legitimate
// Slack call can never hit this branch, so anything that does is either an
// attack or a misconfiguration, and both deserve to show up as a failed
// execution in the error workflow.
const answer = $input.all()[0].json.output;
const ctx = $('Extract Command').first().json;

const url = String(ctx.response_url || '');
if (!/^https:\/\/hooks\.slack\.com\//.test(url)) {
  throw new Error(
    'Refusing to post the answer: response_url is not a Slack endpoint (' +
    (url ? url.slice(0, 80) : 'empty') + '). Only https://hooks.slack.com/ is allowed.'
  );
}

return [{ json: {
  response_url: url,
  payload: {
    response_type: 'in_channel',
    replace_original: false,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: '*NEXUS:*\n' + answer } },
      { type: 'context', elements: [
        { type: 'mrkdwn', text: 'requested by ' + ctx.user + ' · `' + ctx.command + '`' } ] }
    ]
  }
} }];

// ---------------------------------------------------------------------------
// Slack Command Center - AI Agent (VmnIXo7tM30zqawp) -- node "Model Ladder"
// Feeds: OpenRouter Chat Model ({{ $json.orModel }}) + Groq Fallback
// ({{ $json.groqModel }}) on the "AI CRM Agent" agent.
// ---------------------------------------------------------------------------
// n8n's Agent node accepts a maximum of 2 language models, so a deeper
// fallback chain is built as a retry ladder. Each tier swaps the OpenRouter slot.
// 16 Aug 2026: every id below was verified live against OpenRouter -- it exists,
// it is :free (no paid model, per the free-tier rule), and it actually returned
// a tool_call in a real request. The pre-16-Aug ladder had a PAID gemini tier
// plus two dead ids (gemma-4-31b-it:free rate-limited 429, ling-3.0-flash:free
// is 404 free-tier-discontinued), which is why all 4 tiers failed on live
// traffic.
//
// 28 Aug 2026 (KEPT, DO NOT REVERT): the attempt counter is $runIndex, not
// prev.__attempt. The counter used to be read off the incoming item. That works
// on the first pass (from 'Extract Command') but NOT on the retry pass:
// 'AI CRM Agent' runs with onError = continueErrorOutput, and n8n's error
// output emits a fresh { error: ... } item -- it does not carry the input json
// forward. So __attempt was never seen again, every retry computed attempt = 0,
// and Model Ladder <-> AI CRM Agent looped until the 300s executionTimeout,
// firing a full agent invocation (up to 8 tool iterations) each time round.
// On a 1-vCPU box that is the load pattern that has taken it down before.
// $runIndex is n8n's own per-node run counter, maintained by the engine rather
// than carried on the item, so it cannot be lost on the error branch and the
// ladder really terminates. __attempt is still EMITTED for downstream readers;
// only its source changed.
//
// 28 Aug 2026 (KEPT): the prompt is rebuilt from 'Extract Command' rather than
// spread from the incoming item, for the same reason -- on the retry pass the
// incoming item is the error object, so ...prev dropped `command` and
// 'AI CRM Agent' (whose text field is an expression on $json.command) was
// re-run with an empty prompt. 'Extract Command' is on the single inbound path
// and has always run by the time this node executes; the lookup is still
// wrapped in try/catch because $() throws on a node that did not run, and a
// ladder must never be the thing that kills the execution.
//
// 31 Aug 2026 -- MODEL IDS BROUGHT IN LINE WITH BDC / MASTER ROUTER.
// This workflow carried the same two dead ids Lead Escalation did. It has
// effectively zero executions (it sits behind an Auth Gate that Slack's own
// signed request cannot satisfy), so the dead models were never exercised
// here -- which is precisely why they survived two rounds of fixes. Fixed now
// so that the day the Auth Gate is sorted out, this agent does not fail on its
// first real command:
//
//   (a) REMOVED the old tier 0, 'nvidia/nemotron-3-ultra-550b-a55b:free'.
//       Dead -- fails with "Cannot read properties of undefined (reading
//       'message')" after burning ~45s (exec 6251 BDC, exec 6253 Router).
//       Keeping it would mean every Slack command waits three quarters of a
//       minute for a corpse before the real model even starts. Ladder goes
//       from 4 tiers to 3.
//
//   (b) groqModel changed from 'llama-3.3-70b-versatile' to
//       'openai/gpt-oss-120b' on EVERY tier. Groq shut llama-3.3-70b-versatile
//       down for free and developer tiers on 16 Aug 2026; their deprecations
//       page names openai/gpt-oss-120b as the replacement, their models page
//       marks the old id Enterprise/Contact-Sales, and it has no row at all in
//       the free-tier rate-limit table. The replacement is production-tier,
//       free-tier callable and supports OpenAI-style tool calling, which this
//       agent requires. Free-tier ceiling: 30 RPM / 1K RPD / 8K TPM / 200K TPD
//       -- tokens-per-minute binds first.
//
// The three tiers below are now IDENTICAL to WhatsApp BDC (BiyHk9ZXxJUVGbf6),
// Master Router (JnlZFAVmFAuNXVya) and Lead Escalation (KI6P1Qcf3MIZakNa).
// That is deliberate: four ladders that disagree about which models exist is
// how a dead id survives in production for two weeks. See MODELS.md.
// ---------------------------------------------------------------------------

const GROQ_FALLBACK = 'openai/gpt-oss-120b';
const TIERS = [
  { orModel: 'nvidia/nemotron-3.5-lightning:free',       groqModel: GROQ_FALLBACK },
  { orModel: 'nvidia/nemotron-3-super-120b-a12b:free',   groqModel: GROQ_FALLBACK },
  { orModel: 'minimax/minimax-m2.7:free',                groqModel: GROQ_FALLBACK }
];

// Engine-owned counter. Cannot be dropped by the continueErrorOutput branch.
const attempt = Number($runIndex) || 0;

// Rebuild the prompt context every pass -- the incoming item is the error
// object on tiers 1..n.
let base = {};
try { base = $('Extract Command').first().json || {}; } catch (e) { base = {}; }

let prev = {};
try { prev = $input.first().json || {}; } catch (e) { prev = {}; }

const isErrorItem = prev.error !== undefined;

if (attempt >= TIERS.length) {
  throw new Error(
    'Slack Command Center model ladder exhausted: all ' + TIERS.length +
    ' tiers failed for command "' + String(base.command || 'unknown').slice(0, 120) +
    '". Tried (openrouter / groq): ' +
    TIERS.map(function (t, i) { return '[' + i + '] ' + t.orModel + ' / ' + t.groqModel; }).join(', ') +
    '.'
  );
}

const out = Object.assign({}, base, {
  __attempt: attempt,
  __maxTiers: TIERS.length,
  orModel: TIERS[attempt].orModel,
  groqModel: TIERS[attempt].groqModel
});

if (!base.command) {
  // Not fatal -- an exception here would kill the execution on a retry, and the
  // agent's own error path reports a missing prompt more usefully than a Code
  // node stack trace does.
  out.__contextMissing = true;
}

if (isErrorItem) {
  out.__lastError = String(
    (prev.error && (prev.error.message || prev.error.description)) || prev.error
  ).slice(0, 300);
}

return [{ json: out }];

// Every node whose success the Audit Log below is about to claim.
// Post Answer to Slack is the entire user-visible output of this workflow: if it
// drops, the person who typed the slash command gets silence.
const CLAIMED = [
  { node: 'Post Answer to Slack', what: 'answer posted back to the Slack caller', critical: true },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results  = CLAIMED.map(check);
const dropped  = results.filter(r => !r.ok);
const fatal    = dropped.filter(r => r.critical);

const status = fatal.length  ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' - ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
} }];

// This node sits on the ONLY inbound path of this workflow: the public webhook
// POST /webhook/slack-command, which until this patch was the last
// unauthenticated public webhook in the system. Every other webhook here
// (Lead Escalation, KYC, ERP Sync, Ask-AI, WhatsApp Send, the drip, the Master
// Router) already checks the caller's Supabase session token; this one did not.
//
// 'Verify JWT' runs with onError = continueRegularOutput, so a rejected token
// arrives as data rather than as a failed HTTP node. Supabase GET
// /auth/v1/user returns the user object on success; no .id means rejected.
//
// 2 Sep 2026: 'Tenant For JWT User' was inserted between 'Verify JWT' and this
// node to look the caller's dealership up in tenant_members. That HTTP node
// REPLACES the item, so the identity check now reaches back to 'Verify JWT' by
// name. The guard itself is unchanged: no .id on the verified user, no entry.
//
// !!! READ THIS BEFORE WIRING THIS URL INTO SLACK !!!
// A Supabase user JWT is the WRONG guard for a Slack slash command. Slack's
// servers cannot carry one, so a real /nexus command from Slack will always be
// rejected while this gate is in place. That is deliberate, and today it costs
// nothing: this workflow has been edited ~70 times and executed ZERO times, so
// there is no working Slack integration to break -- there is only an open door.
// This is a lock on that door, not a Slack integration.
//
// The correct guard for a genuinely Slack-called webhook is Slack request
// signing: HMAC-SHA256 of 'v0:' + X-Slack-Request-Timestamp + ':' + the RAW
// request body, keyed with the app's signing secret, compared in constant time
// against the X-Slack-Signature header, plus a +/-5 minute timestamp window to
// stop replays. Installing that needs three things this offline patch cannot
// supply and must not guess: rawBody enabled on 'SlackWebhook', a matching
// rewrite of 'Extract Command' (which today reads the parsed form object at
// .body), and the signing secret stored in n8n. Do that swap before you claim
// this workflow answers slash commands.
//
// NOTE FOR WHOEVER DOES THAT SWAP: Slack request signing authenticates SLACK,
// not a dealership. The tenant resolution below hangs off the Supabase user in
// the JWT, so replacing this gate with signature verification REMOVES the only
// tenant signal this workflow has. Map the Slack team_id (or the workspace) to
// a tenant at the same time, or the CRM agent goes back to being tenant-blind.
//
// One more thing this gate does NOT do: 'SlackWebhook' responds onReceived, so
// the 200 and the 'NEXUS is on it' ack are already sent before this node runs.
// An unauthorized caller therefore gets 200 + a friendly string, not a 401.
// What the gate actually buys is that the CRM agent, the Supabase writes and
// the Slack post never happen for an unauthenticated caller. That is the real
// win; do not describe it as returning 401.
let auth = {};
try { auth = $('Verify JWT').first().json || {}; } catch (e) { auth = {}; }
if (!auth.id) {
  // The '[NEXUS-UNATTRIBUTED]' prefix below is a contract with the NEXUS Error
  // Handler (iYJkh1kztWxZXDbT). An execution that failed BEFORE it authenticated
  // its caller belongs to no dealership, so that workflow omits tenant_id and
  // audit_log's own DEFAULT nexus_default_tenant_id() retains the row under the
  // quarantine tenant -- visible to nexus_quarantine_census(), unreadable by any
  // dealership -- instead of appending an anonymous stranger's row to Tenant A'
  // audit trail. Keep the marker at the START of the message: the handler tests
  // position 0, so a copy embedded in a request payload cannot trigger it.
  throw new Error('[NEXUS-UNATTRIBUTED] Slack Command Center rejected: unauthorized. A valid Supabase session token is required in the Authorization header. (Slack itself cannot send one -- see the comment in this node.)');
}

// Re-emit the ORIGINAL request untouched so the downstream node sees exactly
// the shape it saw before this guard was inserted.
return $('SlackWebhook').all();
